import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { ExtensionFactory } from '@earendil-works/pi-coding-agent';
import { Type } from 'typebox';
import type {
  DiscriminatorStyle,
  ProgramReferenceData,
  ReferenceInstruction,
  ReferenceProgram,
} from './program-reference-data.ts';

/**
 * Built-in Solana program reference: an always-on index for the system prompt and an offline lookup tool for the details.
 * The data is generated by scripts/gen-program-reference.ts from pinned public sources. Nothing here touches the network,
 * the knowledge service or any credential.
 */
export const PROGRAM_REFERENCE_TOOL = 'program_reference';

let loaded: ProgramReferenceData | undefined;
export function programReference(): ProgramReferenceData {
  loaded ??= JSON.parse(
    readFileSync(new URL('./program-reference.json', import.meta.url), 'utf8'),
  ) as ProgramReferenceData;
  return loaded;
}

// ---------------------------------------------------------------- index

const STYLE_TAG: Record<DiscriminatorStyle, string> = {
  u8: 'u8',
  u32: 'u32',
  anchor8: 'a8',
  count: 'count',
  none: '-',
};
/** Applications with more instructions than this list their most user-facing ones first and count the rest. */
const APPLICATION_NAME_LIMIT = 12;
const USER_OPERATION =
  /swap|buy|sell|trade|deposit|withdraw|borrow|repay|liquidat|stake|mint|burn|transfer|place|cancel|settle|open|close|add.*liquidity|remove.*liquidity|collect|claim|list|bid|create|vote|propose|execute|route/i;
const ADMIN_OPERATION =
  /admin|config|authority|whitelist|update|set|init|migrate|pause|emergency|protocol|reward|fee|refresh|oracle|reserve/i;
/** Setup instructions are shown first (the SETUP_NAME_LIMIT shortest, which are the plain forms) so a capped list never hides how to create the program's accounts. */
const SETUP_OPERATION = /^(?:initialize|init|create|new)(?:_|$)/i;
const SETUP_NAME_LIMIT = 4;
const RETIRED = /^(?:removed|legacy|deprecated)/i;

const rankOf = (name: string): number =>
  USER_OPERATION.test(name) && !ADMIN_OPERATION.test(name) ? 2 : ADMIN_OPERATION.test(name) ? 0 : 1;

const NAMES_ONLY = '(names only)';
const VERSION_SUFFIX = /_?v\d+$/i;

function indexNames(program: ReferenceProgram): string {
  const live = program.instructions.filter((ix) => !RETIRED.test(ix.name)).map((ix) => ix.name);
  const limit = program.category === 'application' ? APPLICATION_NAME_LIMIT : program.indexHint ? 28 : Infinity;
  if (live.length <= limit) return live.join(',');
  // A capped list shows one name per family: buy, not buy_v2 and buy_v3 as well.
  const bases = new Set<string>();
  const families = live.filter((name) => {
    const base = name.replace(VERSION_SUFFIX, '');
    return !bases.has(base) && bases.add(base);
  });
  const ranked = families.map((name, order) => ({ name, order, rank: rankOf(name) }));
  const setup = ranked
    .filter((entry) => SETUP_OPERATION.test(entry.name))
    .sort((a, b) => a.name.length - b.name.length || a.order - b.order)
    .slice(0, SETUP_NAME_LIMIT);
  const rest = ranked
    .filter((entry) => !setup.includes(entry))
    .sort((a, b) => b.rank - a.rank || a.order - b.order)
    .slice(0, limit - setup.length);
  const shown = [...setup, ...rest].sort((a, b) => a.order - b.order).map((entry) => entry.name);
  return `${shown.join(',')} +${live.length - shown.length} more${program.indexHint ? `: ${program.indexHint}` : ''}`;
}

/** The compact index for every session's system prompt. Pure function of the checked-in data, so it is byte-identical across sessions. */
export function programReferenceIndex(data: ProgramReferenceData = programReference()): string {
  const line = (program: ReferenceProgram) =>
    `${program.name} ${program.id} [${STYLE_TAG[program.style]}] ${indexNames(program)}` +
    `${program.count ? ` (${program.count.lead})` : ''}${program.factsOnly ? ` ${NAMES_ONLY}` : ''}${program.standalone ? ' (standalone)' : ''}${program.clients?.length ? ` | client: ${program.clients.join(' | ')}` : ''}`;
  const section = (title: string, category: ReferenceProgram['category']) =>
    `${title}\n${data.programs
      .filter((program) => program.category === category)
      .map(line)
      .join('\n')}`;
  const words = (...parts: string[]) => parts.join(' ');
  // Model-facing text: its bytes are pinned by test/prompt-lock.test.ts.
  const preamble = words(
    words(
      'Solana program reference (built in, offline; generated from pinned public interfaces).',
      'Use it instead of recalling program ids, instruction tags or account lists from memory, and instead of searching for them.',
    ),
    words(
      `Call ${PROGRAM_REFERENCE_TOOL}({program, instruction?}) for the discriminator bytes, accounts in order with signer/writable flags, and argument`,
      'types of any listed program or instruction (instruction "*" returns all of a program\'s instructions in one call);',
      'names may be partial and any case.',
    ),
    words(
      'Line format: name program-id [instruction tag] instruction names | client:',
      "the program's official npm TypeScript client.",
      'Tags: u8 = 1-byte instruction tag, u32 = 4-byte little-endian instruction index, a8 = 8-byte Anchor discriminator, count = no',
      'tag, the leading field is a count that varies and each value is a distinct prefix, - = no tag. "+N more" means the tool lists N',
      `further instructions. ${NAMES_ONLY} = no argument types or account flags recorded:`,
      'take arguments from the installed client or its bundled IDL.',
      '(standalone) = the whole lifecycle runs on accounts your wallet creates;',
      'other applications need existing deployment state.',
    ),
    words(
      'Signature precompiles (Ed25519, Secp256k1, Secp256r1) verify several signatures per instruction, although common SDK helpers',
      'emit one: byte 0 is the count, and offset records may point at the same signature, key and message bytes, in this or another',
      'instruction of the transaction, so one buffer serves many records (repeated records re-verify;',
      'they do not prove distinct signers).',
      'Records are 14 bytes after a 2-byte header (Ed25519, Secp256r1) or 11 bytes after a 1-byte header (Secp256k1);',
      'Secp256r1 allows 1 to 8 per instruction.',
    ),
  );
  return `${preamble}\n${section('Native and SPL programs:', 'native')}\n${section('Applications (most used on Solana by DefiLlama volume and TVL, plus oracle, multisig and NFT standards):', 'application')}`;
}

/** Official program client packages from the reference that are installed in the workspace, as "name version", for the initial toolchain report. */
/** Clients installed in any of the given roots' node_modules: the task's own, and the locked dependency set the sandbox mounts read-only over it. */
export function installedProgramClients(
  roots: readonly string[],
  data: ProgramReferenceData = programReference(),
): string[] {
  const names = [...new Set(data.programs.flatMap((program) => program.clients ?? []))];
  return names.flatMap((name) => {
    for (const root of roots) {
      try {
        const version = (
          JSON.parse(readFileSync(join(root, 'node_modules', name, 'package.json'), 'utf8')) as { version?: unknown }
        ).version;
        return [typeof version === 'string' ? `${name} ${version}` : name];
      } catch {
        /* not installed under this root */
      }
    }
    return [];
  });
}

// ---------------------------------------------------------------- lookup

const normalise = (text: string): string => text.toLowerCase().replace(/[^a-z0-9]/g, '');
const words = (text: string): string[] =>
  text
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);

function distance(a: string, b: string): number {
  let row = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const next = [i];
    for (let j = 1; j <= b.length; j++)
      next[j] = Math.min(row[j]! + 1, next[j - 1]! + 1, row[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1));
    row = next;
  }
  return row[b.length]!;
}

/** Score of a query against one candidate name: exact spelling, whole-word match, prefix, substring, then edit distance. */
function score(query: string, candidate: string): number {
  const q = normalise(query),
    c = normalise(candidate);
  if (!q) return 0;
  if (q === c) return 1000;
  const queryWords = words(query),
    candidateWords = words(candidate);
  if (queryWords.length && queryWords.every((word) => candidateWords.includes(word))) return 600;
  if (c.startsWith(q)) return 500;
  if (c.includes(q)) return 400;
  return Math.round(100 * Math.max(0, 1 - distance(q, c) / Math.max(q.length, c.length)));
}

interface Ranked<T> {
  item: T;
  score: number;
}
/** Best first; ties go to the shorter name, then source order. */
function rank<T>(query: string, items: T[], names: (item: T) => string[]): Ranked<T>[] {
  return items
    .map((item, order) => ({
      item,
      order,
      score: Math.max(...names(item).map((name) => score(query, name))),
      size: Math.min(...names(item).map((name) => name.length)),
    }))
    .sort((a, b) => b.score - a.score || a.size - b.size || a.order - b.order)
    .map(({ item, score: value }) => ({ item, score: value }));
}
const CLOSE = 400;
const suggestions = <T>(ranked: Ranked<T>[], name: (item: T) => string): string =>
  ranked
    .slice(0, 5)
    .map((r) => name(r.item))
    .join(', ');

function findProgram(query: string): Ranked<ReferenceProgram>[] {
  const programs = programReference().programs;
  const byId = programs.find((program) => program.id === query.trim());
  if (byId) return [{ item: byId, score: 1000 }];
  return rank(query, programs, (program) => [program.name]);
}
const instructionNames = (ix: ReferenceInstruction): string[] => (ix.alias ? [ix.name, ix.alias] : [ix.name]);

const bytesOf = (hex: string): number[] =>
  Array.from({ length: hex.length / 2 }, (_, i) => parseInt(hex.slice(2 * i, 2 * i + 2), 16));
const flags = (account: { signer?: boolean | 'either'; writable?: boolean; optional?: boolean }): string =>
  [
    account.signer === 'either' ? 'signer-or-not' : account.signer ? 'signer' : '',
    account.writable ? 'writable' : '',
    account.optional ? 'optional' : '',
  ]
    .filter(Boolean)
    .join(' ');

const GITHUB_RAW = /^https:\/\/raw\.githubusercontent\.com\/([^/]+\/[^/]+)\/([0-9a-f]{40})\/(.+)$/;
const NPM_CDN = /^https:\/\/cdn\.jsdelivr\.net\/npm\/((?:@[^/]+\/)?[^/@]+)@([^/]+)\/(.+)$/;
/** The call that fetches the program's interface source, read off the pinned url the data was generated from. */
function sourceFetchCall(program: ReferenceProgram): string | undefined {
  const github = GITHUB_RAW.exec(program.source.url);
  if (github) return `source_fetch({repo: "${github[1]}", ref: "${github[2]}", paths: ["${github[3]}"]})`;
  const npm = NPM_CDN.exec(program.source.url);
  return npm ? `source_fetch({npm: "${npm[1]}", version: "${npm[2]}", paths: ["${npm[3]}"]})` : undefined;
}
const sourceLine = (program: ReferenceProgram): string => {
  const call = sourceFetchCall(program);
  const builders =
    program.factsOnly && program.clients?.length
      ? `\nFull layouts: the official client's generated instruction builders give account order, signer/writable flags and argument serializers: read them with source_fetch({npm: "${program.clients[0]}"}), or in node_modules when installed.`
      : '';
  return `${call ? `\nsource: ${call}` : ''}${builders}`;
};

const programHeader = (program: ReferenceProgram): string =>
  `${program.name} ${program.id}\n${program.purpose}${program.deploymentNote ? `\nDeployment: ${program.deploymentNote}` : ''}\nInstruction tag: ${{ u8: '1-byte instruction tag (Token-2022 extensions add a sub-tag byte)', u32: '4-byte little-endian instruction index', anchor8: '8-byte Anchor discriminator', count: 'none; the data starts with a count', none: 'none' }[program.style]}.` +
  `${program.count ? `\nInput dimension: no discriminator; the leading field (${program.count.lead}) varies, bounded by transaction size, and each distinct value is a distinct instruction prefix.\nData layout (${program.count.lead}): ${program.count.layout}.` : ''}` +
  `${program.clients?.length ? `\nOfficial TypeScript client (npm): ${program.clients.join(', ')}. Use it when the project already depends on it.` : ''}` +
  `\nSource: ${program.source.url} (${program.source.version}), licence ${program.source.licence}${program.factsOnly ? '; facts only (names, order and discriminators; no argument types or account flags)' : ''}.` +
  `${sourceLine(program)}${program.rank ? `\nRanking: ${program.rank}.` : ''}`;

function describeInstruction(program: ReferenceProgram, ix: ReferenceInstruction): string {
  const prefix = ix.discriminator
    ? `Instruction data starts with ${ix.discriminator} (bytes [${bytesOf(ix.discriminator).join(',')}]), then the arguments, little-endian.`
    : program.count
      ? `This program has no instruction tag: ${program.count.lead}. Layout: ${program.count.layout}. The leading field is an input dimension: it varies, and each distinct value is a distinct instruction prefix.`
      : 'This program has no instruction tag.';
  const accounts = ix.accounts.length
    ? ix.accounts
        .map((account, i) => `  ${i}. ${account.name}${flags(account) ? ` (${flags(account)})` : ''}`)
        .join('\n')
    : '  none';
  const args =
    ix.args === undefined
      ? `  not recorded here (source licence)${program.clients?.length ? `: take them from the ${program.clients[0]} instruction builder` : ''}`
      : ix.args.length
        ? ix.args.map((arg) => `  ${arg.name}: ${arg.type}`).join('\n')
        : '  none';
  return (
    `${program.name} ${program.id} / ${ix.name}${ix.alias ? ` (source name ${ix.alias})` : ''}\n${program.purpose}${program.deploymentNote ? `\nDeployment: ${program.deploymentNote}` : ''}\n${prefix}\nAccounts in order:\n${accounts}\nArguments:\n${args}` +
    `${ix.note ? `\nNote: ${ix.note}.` : ''}${program.clients?.length ? `\nOfficial TypeScript client (npm): ${program.clients.join(', ')}.` : ''}\nSource: ${program.source.url} (${program.source.version}), licence ${program.source.licence}${program.factsOnly ? '; facts only: names, order and discriminators, no argument types or signer/writable flags' : ''}.${sourceLine(program)}`
  );
}

export const PROGRAM_REFERENCE_RESULT_LIMIT = 16_000;
const cap = (text: string): string =>
  Buffer.byteLength(text) <= PROGRAM_REFERENCE_RESULT_LIMIT
    ? text
    : `${Buffer.from(text)
        .subarray(0, PROGRAM_REFERENCE_RESULT_LIMIT)
        .toString('utf8')
        .replace(/\n[^\n]*$/, '')}\n[truncated: ask for one instruction]`;

/** `instruction: "*"` asks for every instruction of the program in one response. */
const ALL_INSTRUCTIONS = '*';

const nameOf = (ix: ReferenceInstruction): string => `${ix.name}${ix.alias ? ` (${ix.alias})` : ''}`;
const summaryRow = (ix: ReferenceInstruction): string =>
  `  ${nameOf(ix)} ${ix.discriminator || 'no tag'}, ${ix.accounts.length} accounts`;
const compactAccount = (account: ReferenceInstruction['accounts'][number]): string =>
  `${account.name}${flags(account) ? `(${flags(account).replace(/ /g, '+')})` : ''}`;
const detailedRow = (ix: ReferenceInstruction): string =>
  `  ${nameOf(ix)} ${ix.discriminator || 'no tag'} | accounts: ${ix.accounts.map(compactAccount).join(', ') || 'none'} | args: ${
    ix.args === undefined ? 'not recorded' : ix.args.map((arg) => `${arg.name}:${arg.type}`).join(', ') || 'none'
  }`;
const namesRow = (ix: ReferenceInstruction): string =>
  `  ${nameOf(ix)} ${ix.discriminator || 'no tag'} | accounts: ${ix.accounts.map((account) => account.name).join(', ') || 'none'} | args: ${
    ix.args === undefined ? 'not recorded' : ix.args.map((arg) => arg.name).join(', ') || 'none'
  }`;

/** One line per instruction. A program too large for the result limit steps down to names only, then to counts, and says how to get the rest. */
function allInstructions(program: ReferenceProgram, note: string): string {
  const tiers: Array<[string, (ix: ReferenceInstruction) => string]> = [
    ['name, discriminator hex, accounts in order with flags, argument types', detailedRow],
    [
      'name, discriminator hex, account names and argument names only (the program has too many instructions for full detail; ask for one instruction for types and flags)',
      namesRow,
    ],
    [
      'name, discriminator hex and account count only (the program has too many instructions for more; ask for one instruction, or a partial name, for accounts and arguments)',
      summaryRow,
    ],
  ];
  const render = ([what, row]: (typeof tiers)[number]) =>
    `${programHeader(program)}${note}\nAll ${program.instructions.length} instructions, one per line (${what}):\n${program.instructions.map(row).join('\n')}`;
  return cap(
    render(
      tiers.find((tier) => Buffer.byteLength(render(tier)) <= PROGRAM_REFERENCE_RESULT_LIMIT) ??
        tiers[tiers.length - 1]!,
    ),
  );
}

/** Answer for the program_reference tool. Never throws: an unknown name gets the closest matches instead. */
export function lookupProgramReference(program: string, instruction?: string): string {
  const programs = findProgram(program);
  const best = programs[0];
  if (!best || best.score < CLOSE) {
    return `No program matches "${program}". Closest: ${suggestions(programs, (p) => `${p.name} (${p.id})`)}.`;
  }
  const others = programs.slice(1).filter((candidate) => candidate.score >= CLOSE);
  const note = others.length ? `\nOther programs also match "${program}": ${suggestions(others, (p) => p.name)}.` : '';
  const target = best.item;
  if (!instruction) {
    return cap(
      `${programHeader(target)}${note}\nInstructions (name, discriminator hex, account count; ask for one instruction for accounts and arguments, or "${ALL_INSTRUCTIONS}" for all of them in one call):\n${target.instructions.map(summaryRow).join('\n')}`,
    );
  }
  if (instruction.trim() === ALL_INSTRUCTIONS) return allInstructions(target, note);
  const matches = rank(instruction, target.instructions, instructionNames);
  const top = matches[0];
  if (!top || top.score < CLOSE)
    return `${target.name} has no instruction matching "${instruction}". Closest: ${suggestions(matches, (ix) => ix.name)}.`;
  const alsoClose = matches.slice(1).filter((candidate) => candidate.score >= CLOSE);
  const alternatives =
    top.score < 1000 && alsoClose.length
      ? `\nOther instructions also match "${instruction}": ${suggestions(alsoClose, (ix) => ix.name)}.`
      : '';
  return cap(`${describeInstruction(target, top.item)}${note}${alternatives}`);
}

export const programReferenceExtension: ExtensionFactory = (pi) => {
  pi.registerTool({
    name: PROGRAM_REFERENCE_TOOL,
    label: 'Solana program reference',
    description:
      'Offline reference for Solana programs: given a program name or id (partial names, any case), list its instructions with discriminators; given an instruction too, return the discriminator bytes in hex, the accounts in order with signer and writable flags, and the argument types; instruction "*" returns every instruction of the program in one call, one line each (use it instead of one call per instruction). Also names the program\'s official npm TypeScript client, and for programs with no instruction tag (signature precompiles, Config) the data layout. Covers native and SPL programs and widely used applications; the system prompt lists them.',
    parameters: Type.Object({
      program: Type.String(),
      instruction: Type.Optional(
        Type.String({
          description: `An instruction name, or "${ALL_INSTRUCTIONS}" for all of the program's instructions`,
        }),
      ),
    }),
    async execute(_id, params) {
      return {
        content: [{ type: 'text', text: lookupProgramReference(params.program, params.instruction) }],
        details: undefined,
      };
    },
  });
};
